import { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { paymentsApi } from '../../api';
import { API_BASE_URL } from '../../utils/constants';
import { exportToExcel, formatExcelAmount, formatExcelDate } from '../../utils/exportExcel';

function mediaUrl(path) {
  if (!path) return '';
  if (/^https?:\/\//i.test(path)) return path;
  return `${API_BASE_URL}${path.startsWith('/') ? path : `/${path}`}`;
}

function statusLabel(status) {
  if (status === 1) return 'Approved';
  if (status === 2) return 'Rejected';
  return 'Pending';
}

function statusClass(status) {
  if (status === 1) return 'badge ok';
  if (status === 2) return 'badge danger';
  return 'badge warn';
}

export default function FundDepositHistory() {
  const [list, setList] = useState([]);
  const [status, setStatus] = useState('all');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [previewUrl, setPreviewUrl] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await paymentsApi.getFundDeposits({
        status: status === 'all' ? undefined : status,
        panel: 'distributor',
      });
      setList(res.data?.data || []);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to load deposit history');
    } finally {
      setLoading(false);
    }
  }, [status]);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <div className="page">
      <div className="page-head">
        <div>
          <h2>Fund Deposit History</h2>
          <p>All distributor fund deposit requests and their status</p>
        </div>
        <div className="toolbar" style={{ margin: 0, padding: 0, border: 'none', background: 'transparent' }}>
          <button
            type="button"
            className="btn"
            onClick={() =>
              exportToExcel({
                filename: 'fund_deposit_history',
                sheetName: 'Deposit History',
                rows: list,
                columns: [
                  { header: 'Date', value: (r) => formatExcelDate(r.createdAt) },
                  { header: 'UID', value: (r) => r.uid ?? '' },
                  { header: 'Amount', value: (r) => formatExcelAmount(r.amount) },
                  { header: 'UTR', value: (r) => r.utr || '' },
                  { header: 'Status', value: (r) => statusLabel(r.status) },
                  { header: 'Tx ID', value: (r) => r.creditTxId || '' },
                  { header: 'Remark', value: (r) => r.remark || '' },
                  { header: 'Reviewed At', value: (r) => formatExcelDate(r.reviewedAt) },
                ],
              })
            }
            disabled={loading || !list.length}
          >
            Export Excel
          </button>
          <Link className="btn primary" to="/fund-deposits">
            Review deposits
          </Link>
        </div>
      </div>

      <div className="toolbar">
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="all">All</option>
          <option value="0">Pending</option>
          <option value="1">Approved</option>
          <option value="2">Rejected</option>
        </select>
        <button type="button" className="btn" onClick={load}>
          Refresh
        </button>
      </div>

      {error ? <div className="alert error">{error}</div> : null}

      {loading ? (
        <p>Loading history...</p>
      ) : (
        <div className="table-wrap">
          <table className="table">
            <thead>
              <tr>
                <th>Date</th>
                <th>UID</th>
                <th>Amount</th>
                <th>UTR</th>
                <th>Proof</th>
                <th>Status</th>
                <th>Tx</th>
                <th>Remark</th>
                <th>Reviewed</th>
              </tr>
            </thead>
            <tbody>
              {list.length === 0 ? (
                <tr>
                  <td colSpan={9}>No deposit history found.</td>
                </tr>
              ) : (
                list.map((row) => {
                  const proof = row.proofUrl ? mediaUrl(row.proofUrl) : null;
                  return (
                    <tr key={row._id}>
                      <td>{row.createdAt ? new Date(row.createdAt).toLocaleString() : '—'}</td>
                      <td>{row.uid}</td>
                      <td>₹{Number(row.amount || 0).toLocaleString()}</td>
                      <td>
                        <code>{row.utr || '—'}</code>
                      </td>
                      <td>
                        {proof ? (
                          <button
                            type="button"
                            className="btn ghost"
                            style={{ padding: 4 }}
                            onClick={() => setPreviewUrl(proof)}
                            title="Click to enlarge"
                          >
                            <img
                              src={proof}
                              alt="Payment proof"
                              style={{
                                width: 56,
                                height: 56,
                                objectFit: 'cover',
                                borderRadius: 6,
                                display: 'block',
                              }}
                            />
                          </button>
                        ) : (
                          '—'
                        )}
                      </td>
                      <td>
                        <span className={statusClass(row.status)}>{statusLabel(row.status)}</span>
                      </td>
                      <td>{row.creditTxId || '—'}</td>
                      <td>{row.remark || '—'}</td>
                      <td>
                        {row.reviewedAt ? new Date(row.reviewedAt).toLocaleString() : '—'}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      )}

      {previewUrl ? (
        <div
          role="dialog"
          aria-modal="true"
          onClick={() => setPreviewUrl(null)}
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(15, 23, 42, 0.72)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
            padding: 24,
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              background: '#fff',
              borderRadius: 12,
              padding: 16,
              maxWidth: '90vw',
              maxHeight: '90vh',
              display: 'flex',
              flexDirection: 'column',
              gap: 12,
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12 }}>
              <strong>Payment proof</strong>
              <button type="button" className="btn ghost" onClick={() => setPreviewUrl(null)}>
                Close
              </button>
            </div>
            <img
              src={previewUrl}
              alt="Payment proof full"
              style={{ maxWidth: '85vw', maxHeight: '75vh', objectFit: 'contain', borderRadius: 8 }}
            />
          </div>
        </div>
      ) : null}
    </div>
  );
}
